// Simula una máquina con la misma lógica que simulador.py
const DEGRADACION = 60, FALLA = 20, PROB = 0.005;
let st = context.get('st') || { estado: 'normal', contador: 0 };

st.contador++;
if (st.estado === 'normal' && Math.random() < PROB) st = { estado: 'degradacion', contador: 0 };
else if (st.estado === 'degradacion' && st.contador >= DEGRADACION) st = { estado: 'falla', contador: 0 };
else if (st.estado === 'falla' && st.contador >= FALLA) st = { estado: 'normal', contador: 0 };
context.set('st', st);

const s = st.estado === 'degradacion' ? st.contador / DEGRADACION : (st.estado === 'falla' ? 1 : 0);
const ruido = (d) => (Math.random() * 2 - 1) * d;

msg.topic = 'fabrica/maquina-nodered/lecturas';
msg.payload = {
    maquina_id: 'maquina-nodered',
    timestamp: new Date().toISOString(),
    temperatura: +(60 + 30 * s + ruido(1)).toFixed(2),
    vibracion: +(2 + 6 * s * s + ruido(0.2)).toFixed(3),
    presion: +(5 - 1.5 * s + ruido(0.1)).toFixed(3),
    rpm: +(1500 - 200 * s + ruido(10)).toFixed(1),
    estado: st.estado
};
return msg;
